import data from "@/data/results.json";

/** Static numbers generated by scripts/export_frontend_data.py from saved result files. */
export const results = data;

export type WarmRow = (typeof data.warm_test_k10)[number];

export function warm(model: string): WarmRow {
  const row = data.warm_test_k10.find((r) => r.model === model);
  if (!row) throw new Error(`Missing warm result for ${model}`);
  return row;
}

export function m2Row(n: number, method: "m2" | "popularity") {
  const row = data.m2_test_k10.find((r) => r.n === n && r.method === method);
  if (!row) throw new Error(`Missing M2 result for n=${n} ${method}`);
  return row;
}

export function m1Grid(lambda: number, beta: number) {
  const row = data.m1_validation_grid_k10.find((r) => r.lambda === lambda && r.beta === beta);
  if (!row) throw new Error(`Missing M1 grid point lambda=${lambda} beta=${beta}`);
  return row;
}
